    if(window.location.href.includes('offscreen-canvas-demo=')) {
      return (<><RotatingBoxPurple /></>)
    }
    if (areWeChild) {
      return (<><AtwBoxChildFrame /></>)
    } else {
      return <MetaMainContain />
    }
  }
  React.useEffect(() => {

    console.log("App useEffect")
