      <Canvas id="canvas" ref={canvasRef}   >
        <ambientLight intensity={0.5} />
        <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} />
        <pointLight position={[-10, -10, -10]} />
        {/* <ClickBox position={[-1.2, 0, 0]} />
      // <ClickBox position={[1.2, 0, 0]} /> */}

        <CameraWalker />


        {/* <Grid size={10} /> */}

        {whichAtwBox()}

        {/* <AtwBox /> */}

        {/* <DrawDogComponent /> */}

        {/* <Stats showPanel={0} /> */}
